from dataclasses import dataclass
from typing import Any, Callable, Optional


@dataclass
class TaskResult:
    status: str
    func_name: str
    result: Any = None
    error: Optional[str] = None


class TaskRunner:
    def __init__(self):
        self.tasks: list[tuple[Callable, tuple, dict]] = []
        self.results: list[TaskResult] = []

    def add_task(self, func: Callable, *args, **kwargs) -> None:
        self.tasks.append((func, args, kwargs))

    def run(self) -> list[TaskResult]:
        self.results = []
        for func, args, kwargs in self.tasks:
            try:
                result = func(*args, **kwargs)
                self.results.append(TaskResult(
                    status="ok",
                    func_name=func.__name__,
                    result=result,
                ))
            except Exception as e:
                self.results.append(TaskResult(
                    status="error",
                    func_name=func.__name__,
                    error=str(e),
                ))
        return self.results

    @property
    def summary(self) -> dict[str, int]:
        successes = sum(1 for r in self.results if r.status == "ok")
        errors = sum(1 for r in self.results if r.status == "error")
        return {
            "total": len(self.results),
            "successes": successes,
            "errors": errors,
        }

    def get_errors(self) -> list[TaskResult]:
        return [r for r in self.results if r.status == "error"]

    def get_successes(self) -> list[TaskResult]:
        return [r for r in self.results if r.status == "ok"]
